package com.novacommerce.order.domain; import static org.assertj.core.api.Assertions.*; import com.novacommerce.order.application.CheckoutHasher; import com.novacommerce.order.domain.cart.*; import com.novacommerce.order.domain.order.*; import java.math.BigDecimal; import java.time.Instant; import java.util.*; import org.junit.jupiter.api.Test;
class OrderDomainTests{@Test void cartQuantityAndStateRules(){Instant n=Instant.EPOCH;Cart c=new Cart(UUID.randomUUID(),n);UUID v=UUID.randomUUID();c.add(v,2,n);c.add(v,3,n);assertThat(c.getItems().iterator().next().getQuantity()).isEqualTo(5);c.beginCheckout(n);assertThat(c.getStatus()).isEqualTo(CartStatus.CHECKOUT_PENDING);c.reopen(n);assertThat(c.getStatus()).isEqualTo(CartStatus.ACTIVE);}@Test void orderSnapshotsMoneyAndTransitions(){CustomerOrder o=new CustomerOrder(UUID.randomUUID(),UUID.randomUUID(),"k","h","USD",Instant.EPOCH);o.addItem(UUID.randomUUID(),UUID.randomUUID(),"Product","product","Variant","SKU",Map.of(),3,new BigDecimal("10.25"));assertThat(o.getMerchandiseTotal()).isEqualByComparingTo("30.75");UUID r=UUID.randomUUID();o.inventoryReserved(r,Instant.EPOCH.plusSeconds(60),Instant.EPOCH);assertThat(o.getStatus()).isEqualTo(OrderStatus.AWAITING_PAYMENT);assertThat(o.getItems().getFirst().getUnitPrice()).isEqualByComparingTo("10.25");}@Test void checkoutHashIsOrderIndependentAndQuantitySensitive(){CheckoutHasher h=new CheckoutHasher();UUID owner=UUID.randomUUID(),cart=UUID.randomUUID(),a=UUID.randomUUID(),b=UUID.randomUUID();Instant n=Instant.EPOCH;assertThat(h.hash(owner,cart,List.of(new CartItem(a,1,n),new CartItem(b,2,n)))).isEqualTo(h.hash(owner,cart,List.of(new CartItem(b,2,n),new CartItem(a,1,n))));assertThat(h.hash(owner,cart,List.of(new CartItem(a,1,n)))).isNotEqualTo(h.hash(owner,cart,List.of(new CartItem(a,2,n))));}}
